INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 20, 'theory', 'Quiz: storage engines');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 20, 0, 'Why is a commit fast in a database with a write-ahead log, even though the data on disk is not updated yet?', '["Because the database does not write to disk at all", "It is enough to flush the log to disk sequentially; data pages are written later, and after a crash the log is replayed", "Because the log is kept in RAM", "Because the commit is postponed until the next reboot"]', 1, 'The log is written only at the end — that is fast, and it contains everything needed to restore the changes. Pages can be written at a convenient time and in any order.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 20, 1, 'What does an LSM tree do on a write?', '["Updates the needed page in place", "Immediately rebuilds the index on disk", "Writes to the log and to the in-memory memtable, then flushes it to disk as an immutable sorted file; background compaction later merges the files", "Writes every change to all the files"]', 2, 'Writes are always sequential. The price is background compaction and a more complex read — a value may lie in any of several files.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 20, 2, 'Why does each file of an LSM tree keep a Bloom filter?', '["To quickly answer \"definitely not\" and avoid reading a file that surely lacks the key", "To compress the data", "To encrypt the file", "To determine the order of writes"]', 0, 'The filter allows false "maybe" answers but never false "no" answers: the extra reads disappear, and the right ones remain.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 20, 3, 'Why do analytical queries benefit from columnar storage?', '["Because all the values of a row lie together", "Because columns cannot be modified", "Because columns do not need a log", "The query reads only the needed columns, and uniform values compress well"]', 3, 'An average over one column out of a hundred reads 1% of the data; repeats are replaced with a "value — repeat count" pair, and strings with numbers via a dictionary.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 20, 4, 'What does a call to fsync guarantee?', '["That the write reached the operating system cache", "That the data is physically written to the device and will survive a power failure", "That the file is encrypted", "That the file will never change again"]', 1, 'write() returns when the data is in the OS cache. Without fsync, an acknowledged commit can be lost; that is why a commit waits for the log flush.');
